## Phase 3: Frontend Component Architecture

### 3.1 Component Structure Decision

**Recommendation: Hybrid Approach**

Keep the monolithic `App.vue` for the main layout, but extract CRUD functionality into reusable composables and dialog components.

**Rationale**:
- **Monolithic App.vue**: Good for this project size (single page, simple navigation)
- **Composables**: Reusable logic for CRUD operations
- **Dialog Components**: Reusable UI for create/edit forms
- **Avoids over-engineering**: No need for full component hierarchy yet

### 3.2 Create CRUD Composable

**File**: `C:\Users\31936\Desktop\AgentMemory\frontend\src\composables\useCrudOperations.ts`

```typescript
import { ref } from 'vue'
import axios from 'axios'
import { ElMessage, ElMessageBox } from 'element-plus'

const API_BASE = 'http://localhost:8080/api'

interface CrudOptions {
  resource: string
  onSuccess?: (action: string, data?: any) => void
  onError?: (error: any) => void
}

export function useCrudOperations(options: CrudOptions) {
  const { resource, onSuccess, onError } = options
  const loading = ref(false)

  // List all records
  const list = async () => {
    try {
      const res = await axios.get(`${API_BASE}/${resource}`)
      return res.data
    } catch (error) {
      ElMessage.error('加载失败')
      onError?.(error)
      throw error
    }
  }

  // Get single record
  const get = async (id: string) => {
    try {
      const res = await axios.get(`${API_BASE}/${resource}/${id}`)
      return res.data
    } catch (error) {
      ElMessage.error('加载详情失败')
      onError?.(error)
      throw error
    }
  }

  // Create new record
  const create = async (data: any) => {
    loading.value = true
    try {
      const res = await axios.post(`${API_BASE}/${resource}`, data)
      ElMessage.success('创建成功')
      onSuccess?.('create', res.data)
      return res.data
    } catch (error: any) {
      const message = error.response?.data?.message || '创建失败'
      ElMessage.error(message)
      onError?.(error)
      throw error
    } finally {
      loading.value = false
    }
  }

  // Update existing record
  const update = async (id: string, data: any) => {
    loading.value = true
    try {
      const res = await axios.put(`${API_BASE}/${resource}/${id}`, data)
      ElMessage.success('更新成功')
      onSuccess?.('update', res.data)
      return res.data
    } catch (error: any) {
      const message = error.response?.data?.message || '更新失败'
      ElMessage.error(message)
      onError?.(error)
      throw error
    } finally {
      loading.value = false
    }
  }

  // Delete record (soft delete)
  const remove = async (id: string) => {
    try {
      await ElMessageBox.confirm('确定要删除这条记录吗？', '确认删除', {
        type: 'warning'
      })

      loading.value = true
      await axios.delete(`${API_BASE}/${resource}/${id}`)
      ElMessage.success('删除成功')
      onSuccess?.('delete')
    } catch (error: any) {
      if (error !== 'cancel') {
        const message = error.response?.data?.message || '删除失败'
        ElMessage.error(message)
        onError?.(error)
      }
      throw error
    } finally {
      loading.value = false
    }
  }

  // Export all records
  const exportAll = async () => {
    try {
      const res = await axios.get(`${API_BASE}/${resource}/export`, {
        responseType: 'blob'
      })

      // Create download link
      const url = window.URL.createObjectURL(new Blob([res.data]))
      const link = document.createElement('a')
      link.href = url
      link.setAttribute('download', `${resource}_${Date.now()}.json`)
      document.body.appendChild(link)
      link.click()
      link.remove()

      ElMessage.success('导出成功')
    } catch (error) {
      ElMessage.error('导出失败')
      onError?.(error)
      throw error
    }
  }

  // Export single record
  const exportSingle = async (id: string) => {
    try {
      const res = await axios.get(`${API_BASE}/${resource}/${id}/export`, {
        responseType: 'blob'
      })

      const url = window.URL.createObjectURL(new Blob([res.data]))
      const link = document.createElement('a')
      link.href = url
      link.setAttribute('download', `${resource}_${id}_${Date.now()}.json`)
      document.body.appendChild(link)
      link.click()
      link.remove()

      ElMessage.success('导出成功')
    } catch (error) {
      ElMessage.error('导出失败')
      onError?.(error)
      throw error
    }
  }

  return {
    loading,
    list,
    get,
    create,
    update,
    remove,
    exportAll,
    exportSingle
  }
}
```

