```typescript
// Import composable
import { useCrudOperations } from './composables/useCrudOperations'

// CRUD setup for each repository
const errorCrud = useCrudOperations({
  resource: 'errors',
  onSuccess: async (action) => {
    if (action === 'create' || action === 'update' || action === 'delete') {
      await loadAllData() // Refresh data
    }
  }
})

// Dialog state
const errorDialogVisible = ref(false)
const isEditError = ref(false)
const currentError = ref<any>(null)

// Validation rules
const errorRules = {
  title: [{ required: true, message: '请输入标题', trigger: 'blur' }],
  problem: [{ required: true, message: '请描述问题', trigger: 'blur' }],
  solution: [{ required: true, message: '请提供解决方案', trigger: 'blur' }]
}

// CRUD methods
const openErrorDialog = () => {
  isEditError.value = false
  currentError.value = null
  errorDialogVisible.value = true
}

const editError = (row: any) => {
  isEditError.value = true
  currentError.value = { ...row }
  // Convert tags array to comma-separated string for editing
  if (Array.isArray(currentError.value.tags)) {
    currentError.value.tags = currentError.value.tags.join(', ')
  }
  errorDialogVisible.value = true
}

const deleteError = async (id: string) => {
  await errorCrud.remove(id)
}

const handleErrorSubmit = async (data: any) => {
  // Convert tags string to array
  if (typeof data.tags === 'string') {
    data.tags = data.tags.split(',').map((t: string) => t.trim()).filter((t: string) => t)
  }

  if (isEditError.value) {
    await errorCrud.update(currentError.value.id, data)
  } else {
    await errorCrud.create(data)
  }

  errorDialogVisible.value = false
}

const exportErrors = async () => {
  await errorCrud.exportAll()
}

// Repeat similar setup for other 4 repositories...
```

