  const idxA = Math.min(Math.floor(pathIdx), pathHistory.length - 1);
  const idxB = Math.min(idxA + 1, pathHistory.length - 1);
  const alpha = pathIdx - Math.floor(pathIdx);

  if (pathHistory[idxA] && pathHistory[idxB]) {
