  const t = i / CONFIG.swordCount;
  const radius = t * 10;
  const angle = i * 0.3;
  const depth = t * 25;

  target.set(
    currentTarget.x + Math.cos(angle) * radius,
    currentTarget.y + Math.sin(angle) * radius,
    currentTarget.z - depth
  );

  // 呼吸效果
  target.x += Math.sin(time * 5 + i) * 0.3;
  target.y += Math.cos(time * 5 + i) * 0.3;
}
```

