### 状态管理方案

**配置存储结构**：
```typescript
// src/store.ts
interface ConfigState {
  swordCount: number;
  maxSpeed: number;
  sprintSpeed: number;
  steerForce: number;
  separationDist: number;
  separationForce: number;
}

interface ConfigStore extends ConfigState {
  setConfig: (updates: Partial<ConfigState>) => void;
  resetConfig: () => void;
}

export const useConfigStore = create<ConfigStore>((set, get) => ({
  // 默认值
  swordCount: isMobile ? 200 : 300,
  maxSpeed: 50,
  sprintSpeed: 80,
  steerForce: 40,
  separationDist: 3,
  separationForce: 10,

  setConfig: (updates) => set((state) => ({ ...state, ...updates })),

  resetConfig: () => set({
    swordCount: isMobile ? 200 : 300,
    maxSpeed: 50,
    sprintSpeed: 80,
    steerForce: 40,
    separationDist: 3,
    separationForce: 10,
  }),
}));
```

### 粒子数量动态修改技术处理

**核心挑战**：`InstancedMesh` 实例数量在创建时固定，修改需要重建。

**解决方案**：
```typescript
// src/components/SwordSwarm.tsx
import { useEffect, useRef } from 'react';

export function SwordSwarm() {
  const meshRef = useRef<THREE.InstancedMesh>(null);
  const config = useConfigStore();

  // 监听配置变化
  const prevCountRef = useRef(config.swordCount);

  useEffect(() => {
    if (config.swordCount !== prevCountRef.current) {
      // 更新数组大小
      if (config.swordCount > positions.current.length) {
        for (let i = positions.current.length; i < config.swordCount; i++) {
          positions.current.push(new THREE.Vector3(
            (Math.random() - 0.5) * 20,
            (Math.random() - 0.5) * 15,
            (Math.random() - 0.5) * 10 - 5
          ));
          velocities.current.push(new THREE.Vector3());
        }
      } else {
        positions.current.length = config.swordCount;
        velocities.current.length = config.swordCount;
      }

      prevCountRef.current = config.swordCount;

      // 标记需要重建 mesh（简单方案）
      // 或者使用 dispose + 重新创建（复杂方案）
    }
  }, [config.swordCount]);

  // ... 其余代码
}
```

**简化方案**（推荐）：固定最大容量，只渲染当前配置数量
```typescript
// args 中的实例数使用最大值 500
args={[geometry, material, 500]}

// 在 useFrame 中只更新到 config.swordCount
for (let i = 0; i < config.swordCount; i++) {
  // ... 更新逻辑
}

// 将多余的实例隐藏
for (let i = config.swordCount; i < 500; i++) {
  dummy.scale.set(0, 0, 0);
  dummy.updateMatrix();
  meshRef.current.setMatrixAt(i, dummy.matrix);
}
```

